  const importCheckpoint = useCallback(
    async (raw: string, name: string) => {
      const entry = await withBusy(() =>
        api.libraryImportJson(raw, name.trim() || undefined),
      );
      if (entry) patch({ library: await api.library() });
    },
    [patch, withBusy],
  );

  const forkSession = useCallback(
    async (source: { checkpoint?: string; session?: string }, id: string, label: string) => {
      const res = await withBusy(() =>
        api.forkSession({
          ...source,
          id: id.trim() || undefined,
          label: label.trim() || undefined,
        }),
      );
      if (res) {
        await refreshRun();
        await reloadAll();
        if (res.compatAdvisories.length > 0) {
          patch({ notice: `Forked with advisories: ${res.compatAdvisories.join("; ")}` });
        }
      }
    },
    [patch, refreshRun, reloadAll, withBusy],
  );

  const activateSession = useCallback(
    async (id: string) => {
      const ok = await withBusy(() => api.activateSession(id));
      if (ok) {
        await refreshRun();
        patch({ activeSession: id });
      }
    },
    [patch, refreshRun, withBusy],
  );

  const closeSession = useCallback(
    async (id: string) => {
      const ok = await withBusy(() => api.closeSession(id), `Closed session ${id || "main"}`);
      if (ok) {
        await refreshRun();
        await reloadAll();
      }
    },
    [refreshRun, reloadAll, withBusy],
  );

  const runBranch = useCallback(
    async (args: {
      checkpoint: string;
      name: string;
      policy: string;
      maxActions: number;
      overrides: ActionOverride[];
    }) => {
      const res = await withBusy(
        () => api.labBranch(args),
        `Branch ${args.name || args.checkpoint} finished`,
      );
      if (res) patch({ branches: await api.labBranches() });
      return res;
    },
    [patch, withBusy],
  );

  const deleteBranch = useCallback(
    async (id: string) => {
      await withBusy(async () => {
        await api.labBranchDelete(id);
        // Apply the acknowledged deletion before a fallible list refresh.
        // Pending comparisons of this branch must not revive its old report.
        branchRevisions.current.set(id, (branchRevisions.current.get(id) ?? 0) + 1);
        setState((s) => ({
          ...s,
          branches: s.branches.filter((branch) => branch.id !== id),
          compareA: s.compareA === id ? "" : s.compareA,
          compareB: s.compareB === id ? "" : s.compareB,
          comparison: s.comparison && (s.comparison.aId === id || s.comparison.bId === id)
            ? null
            : s.comparison,
        }));
        patch({ branches: await api.labBranches() });
      });
    },
    [patch, withBusy],
  );

  const compare = useCallback(
    async (a: string, b: string) => {
      if (!a || !b || a === b) {
        patch({ error: "Pick two different branches to compare." });
        return;
      }
      const request = ++comparisonRequest.current;
      const revisionA = branchRevisions.current.get(a) ?? 0;
      const revisionB = branchRevisions.current.get(b) ?? 0;
      const c = await withBusy(() => api.labCompare(a, b));
      if (
        c && request === comparisonRequest.current &&
        revisionA === (branchRevisions.current.get(a) ?? 0) &&
        revisionB === (branchRevisions.current.get(b) ?? 0)
      ) {
        // Selection is an editable draft, independent of the received result.
        patch({ comparison: c });
      }
    },
    [patch, withBusy],
  );

  const clearError = useCallback(() => patch({ error: null }), [patch]);
  const clearNotice = useCallback(() => patch({ notice: null }), [patch]);

  return {
    state,
    reloadAll,
    saveCheckpoint,
    loadCheckpoint,
    deleteCheckpoint,
    importCheckpoint,
    forkSession,
    activateSession,
    closeSession,
    runBranch,
    deleteBranch,
    compare,
    clearError,
    clearNotice,
    setCompareSelection: (a: string, b: string) => patch({ compareA: a, compareB: b }),
  };
}
